export type ReturnLineItemInput = { /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "accepted_quantity": string; "allowed_resolution_types": Array<"refund" | "exchange" | "replacement" | "no_monetary_action">; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "approved_quantity": string; /** Approved quantity that can still be assigned to a new resolution. Every non-canceled resolution reserves its line quantity, including proposed, pending, action-required, failed, and fulfilled resolutions. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "available_resolution_quantity": string; "bundle_components": Array<BundleComponentInput>; "bundle_id"?: string; "buyer_note"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "canceled_quantity": string; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; "decided_by"?: ReturnActorInput; /** RFC3339 timestamp. Format: date-time. */ "decision_at"?: string | globalThis.Date; "decline_reason"?: "not_eligible" | "quantity_unavailable" | "evidence_missing" | "suspected_abuse" | "merchant_discretion" | "other"; "decline_reason_message"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "declined_quantity": string; "description"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "dispositioned_quantity": string; "eligibility": ReturnLineItemEligibilityInput; "fulfillment"?: (({ /** Current hold details. While this field is present, status continues to show the public work status from before the hold. */ "active_hold"?: never; "charges"?: never; /** Completion evidence timestamp. Format: date-time. */ "completed_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "customer_id"?: string; "device_id"?: string; "digital_details"?: DigitalFulfillmentDetailsInput; /** First time this fulfillment reached dispatched. Format: date-time. */ "dispatched_at"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_id"?: never; "line_items": Array<FulfillmentLineItemInput>; "local_delivery_details"?: DeliveryFulfillmentDetailsInput; "location_id"?: string; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; /** Terminal outcome details. The mark_no_show action records its reason here and returns status as failed. */ "outcome"?: never; "packages"?: never; /** First time this fulfillment reached packed. Format: date-time. */ "packed_at"?: never; /** First time this fulfillment reached picked. Format: date-time. */ "picked_at"?: never; "pickup_details"?: PickupFulfillmentDetailsInput; /** Read-only current quantity accounting behavior for this fulfillment state. */ "quantity_effect"?: never; "recipient"?: FulfillmentRecipientInput; /** Provider acceptance state, independent from fulfillment work progress. The accept action sets this field to accepted while status remains pending. */ "request_status"?: never; "service_details"?: ServiceFulfillmentDetailsInput; "shipments"?: never; /** Public work status. Fulfillments with request_status accepted project to status pending. Fulfillments with outcome.outcome_type no_show project to status failed. A fulfillment with active_hold projects to its public work status from before the hold. - `pending`: Work has not started. Start, schedule, accept, hold, cancel, or fail it as supported_actions allows. - `in_progress`: Work has started and is not yet ready or complete. - `ready`: The fulfillment is ready for pickup, handoff, or completion. - `completed`: All fulfillment work completed successfully. - `canceled`: The fulfillment was intentionally canceled and will not continue. - `failed`: The fulfillment could not be completed. Resolve the recorded reason before creating replacement work. - `scheduled`: The fulfillment is scheduled for its recorded service window. - `preparing`: Warehouse or provider preparation is underway. - `picked`: The assigned items have been picked. - `packed`: The assigned items have been packed. - `dispatched`: The fulfillment left its origin for delivery or handoff. */ "status"?: never; /** Read-only actions currently supported for this fulfillment. */ "supported_actions"?: never; /** When the fulfillment entered a terminal state: completed, canceled, or failed. This records the state transition; completed_at records completion evidence supplied for the fulfillment. Format: date-time. */ "terminal_at"?: never; "type": "shipment" | "pickup" | "local_delivery" | "digital" | "service"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; /** Monotonic fulfillment version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version"?: never; }) | (null)); "fulfillment_id": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "handed_off_quantity": string; "image"?: ImageInput; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "inspected_quantity": string; /** RFC3339 timestamp. Format: date-time. */ "inspection_waived_at"?: string | globalThis.Date; "inspection_waived_by"?: ReturnActorInput; "inspection_waiver_reason"?: "policy_override" | "trusted_in_store_handoff" | "merchant_review" | "other"; "inspection_waiver_reason_message"?: string; "is_inspection_required"?: boolean; "is_policy_overridden": boolean; "merchandise_status": "not_required" | "awaiting_handoff" | "in_transit" | "partially_received" | "received" | "inspection_required" | "partially_inspected" | "inspection_review_required" | "disposition_required" | "resolved" | "exception"; "modifiers": Array<OrderLineItemModifierInput>; "name": string; "order_line_item_id": string; /** RFC3339 timestamp. Format: date-time. */ "overridden_at"?: string | globalThis.Date; "overridden_by"?: ReturnActorInput; "override_reason"?: "customer_service_exception" | "policy_correction" | "risk_review" | "merchant_discretion" | "other"; "override_reason_message"?: string; "product_id"?: string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "received_quantity": string; "receiving_location_id"?: string; "refund_timing"?: "after_approval" | "after_handoff" | "after_receipt" | "after_inspection" | "manual"; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "rejected_quantity": string; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "requested_quantity": string; "requested_resolution_type"?: "refund" | "exchange" | "replacement" | "no_monetary_action" | "correction"; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "resolution_count": string; "resolution_mode"?: "automatic" | "manual"; "resolution_status": "not_selected" | "pending" | "partially_fulfilled" | "requires_action" | "fulfilled" | "failed"; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "resolved_quantity": string; "return_id": string; "return_line_item_id": string; "return_reason"?: (({ "category_handles": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "created_at": string | globalThis.Date; "description"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "handle": string; "is_note_required": boolean; "name": string; "return_reason_id": string; "source": "flint" | "merchant"; "status": "active" | "archived"; "supported_actions": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string | globalThis.Date; /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "version": string; }) | (null)); "return_reason_handle": string; "return_reason_id": string; "return_reason_name": string; /** How much of the approved quantity the buyer must physically send back; fractional quantities are not supported. Set 0 for a returnless refund, where the buyer keeps the merchandise and the Return still settles the money. Use an exact numeric string, not a floating-point number. Format: int64. */ "return_required_quantity": string; "return_value": ReturnLineItemValueInput; /** Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "review_required_quantity": string; "selected_options": Array<SelectedProductOptionInput>; "selected_resolution_type"?: "refund" | "exchange" | "replacement" | "no_monetary_action"; "sku"?: string; "status": "requested" | "open" | "completed" | "declined" | "canceled"; "supported_actions": Array<string>; /** RFC3339 timestamp. Format: date-time. */ "updated_at": string | globalThis.Date; "variant_id"?: string; };
